INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (10, 'Jahitan zigzag tidak terbentuk dengan benar', 'Pola zigzag tidak terbentuk sesuai pengaturan atau lebar jahitan berubah-ubah.', 'Mekanisme zigzag tidak bekerja normal, pemasangan jarum atau benang tidak tepat, atau penyetelan mekanisme zigzag kurang sesuai.', 'Periksa mekanisme zigzag, pemasangan jarum DP×5, jalur benang, dan penyetelan lebar zigzag. Pastikan pengaturan tidak melebihi lebar zigzag maksimum 10 mm.', 'Matikan mesin sebelum memeriksa atau menyetel mekanisme zigzag.', 'Data spesifikasi JUKI LZ-2280A dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (10, 'Benang jarum sering putus', 'Benang atas putus berulang kali selama proses menjahit.', 'Jarum rusak atau tidak sesuai, jalur benang kurang tepat, tegangan benang terlalu tinggi, atau benang bergesekan dengan bagian mesin.', 'Periksa jarum DP×5 dan jalur benang. Sesuaikan tegangan benang dengan material dan kondisi jahitan.', 'Matikan mesin sebelum mengganti jarum atau melakukan penyetelan tegangan benang.', 'Data spesifikasi needle JUKI LZ-2280A dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (10, 'Jahitan loncat atau tidak terbentuk', 'Sebagian jahitan tidak terbentuk dan jarum tidak menangkap benang bawah dengan baik.', 'Jarum bengkok atau tidak sesuai, posisi jarum kurang tepat, atau hubungan jarum dengan standard full-rotary hook tidak sesuai.', 'Periksa kondisi dan pemasangan jarum DP×5. Periksa area hook dan pastikan tidak ada kotoran atau gangguan mekanis.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa jarum atau hook.', 'Data spesifikasi needle dan standard full-rotary hook JUKI LZ-2280A dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (10, 'Lebar zigzag tidak sesuai', 'Lebar jahitan zigzag lebih kecil, lebih besar, atau berubah dari pengaturan yang diinginkan.', 'Pengaturan lebar zigzag tidak tepat atau mekanisme zigzag cam-controlled mengalami gangguan.', 'Periksa pengaturan lebar zigzag dan mekanisme cam-controlled. Pastikan lebar tidak melebihi kapasitas maksimum 10 mm.', 'Matikan mesin sebelum memeriksa mekanisme zigzag atau bagian cam.', 'Data spesifikasi maximum zigzag width dan zigzag mechanism JUKI LZ-2280A');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (10, 'Panjang jahitan tidak sesuai', 'Panjang stitch hasil jahitan berbeda dari nilai yang diatur.', 'Pengaturan stitch length tidak tepat atau mekanisme drop feed mengalami gangguan.', 'Periksa pengaturan panjang jahitan dan gerakan drop feed. Sesuaikan secara bertahap dalam batas maksimum stitch length 5 mm.', 'Matikan mesin sebelum memeriksa atau menyetel mekanisme feed.', 'Data spesifikasi stitch length dan drop feed JUKI LZ-2280A');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (10, 'Kain tidak bergerak stabil', 'Kain bergerak tersendat, tertarik, atau panjang jahitan menjadi tidak konsisten.', 'Mekanisme drop feed tidak bekerja normal, tekanan presser foot kurang sesuai, atau permukaan feed dog kotor.', 'Periksa feed dog dan mekanisme drop feed. Bersihkan area feed dan sesuaikan tekanan presser foot dengan material.', 'Matikan mesin sebelum membersihkan atau memeriksa area feed dog.', 'Data spesifikasi feed mechanism dan presser foot JUKI LZ-2280A dan panduan pemeriksaan umum');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (10, 'Jarum patah atau posisi jarum tidak normal', 'Jarum bengkok, patah, atau gerakan jarum tidak normal saat menjahit.', 'Jarum tidak terpasang benar, ukuran jarum tidak sesuai material, atau needle bar mengalami gangguan.', 'Periksa pemasangan dan kondisi jarum DP×5. Pastikan ukuran jarum sesuai material dan periksa gerakan needle bar.', 'Matikan mesin dan lepaskan sumber listrik sebelum mengganti jarum atau memeriksa needle bar.', 'Data spesifikasi needle dan needle bar stroke JUKI LZ-2280A');
INSERT INTO troubleshooting (machine_id, problem, symptoms, possible_cause, solution, safety_notes, source) VALUES (10, 'Pelumasan atau putaran mesin tidak normal', 'Gerakan mesin terasa kasar, suara mekanis meningkat, atau putaran motor tidak stabil.', 'Sistem pelumasan otomatis tidak bekerja normal, kondisi pelumasan kurang baik, atau motor 400 W mengalami gangguan.', 'Periksa sistem automatic lubrication dan kondisi area mekanis. Periksa sambungan dan kondisi motor jika putaran tidak normal.', 'Matikan mesin dan lepaskan sumber listrik sebelum memeriksa sistem pelumasan atau motor.', 'Data spesifikasi lubrication dan motor JUKI LZ-2280A dan panduan pemeriksaan umum');
